<?php
namespace Tests\Feature;
use App\Models\{AttendanceRecord,DevotionSession,Member};use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class PublicCheckInTest extends TestCase {use RefreshDatabase;public function test_open_session_accepts_only_one_member_check_in():void{$session=DevotionSession::create(['name'=>'Sunday Devotion','session_date'=>'2026-11-08','start_time'=>'08:00','end_time'=>'08:45','location'=>'Sanctuary','qr_token'=>'TEST-TOKEN','status'=>'open']);$member=Member::create(['first_name'=>'Ada','last_name'=>'Nwosu','email'=>'ada@example.test','status'=>'active','role'=>'member']);$this->post('/check-in/TEST-TOKEN',['member_id'=>$member->id])->assertSessionHas('success');$this->post('/check-in/TEST-TOKEN',['member_id'=>$member->id])->assertSessionHas('error');$this->assertSame(1,AttendanceRecord::where('member_id',$member->id)->count());}public function test_closed_session_rejects_check_in():void{$session=DevotionSession::create(['name'=>'Closed','session_date'=>'2026-11-01','start_time'=>'08:00','end_time'=>'08:45','location'=>'Sanctuary','qr_token'=>'CLOSED','status'=>'closed']);$member=Member::create(['first_name'=>'Ada','last_name'=>'Nwosu','status'=>'active','role'=>'member']);$this->post('/check-in/CLOSED',['member_id'=>$member->id])->assertStatus(422);}}
